/* ---------- Instagram: barra, sección con fotos y enlaces ---------- */
.ee-navend{display:flex;align-items:center;gap:var(--sp-2)}
.ee-iglink{display:inline-grid;place-items:center;text-decoration:none;color:inherit}
.ee-ig__head{display:grid;gap:var(--sp-2);justify-items:start}
.ee-ig .ee-overline{color:var(--rosa-800)}
.ee-ig__user{font:400 clamp(2rem,6vw,3rem)/1.05 var(--font-display);color:var(--carbon-900);text-decoration:none}
.ee-ig__user:hover{color:var(--rosa-700)}
.ee-ig__head p{font:var(--type-body);color:var(--carbon-700);max-width:46ch;margin:0}
.ee-ig__grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(max(15%,min(28%,170px)),1fr));gap:clamp(6px,1.4vw,14px);width:100%}
.ee-ig__foto{position:relative;display:block;aspect-ratio:1/1;border-radius:16px;overflow:hidden;background:var(--crema-50);border:3px solid var(--crema-50);box-shadow:0 18px 32px -20px rgba(78,23,48,.5);transition:transform var(--dur-base) var(--ease-silk)}
.ee-ig__foto:hover{transform:translateY(-4px)}
.ee-ig__foto:focus-visible{outline:2px solid var(--rosa-700);outline-offset:3px}
.ee-ig__foto img{width:100%;height:100%;object-fit:cover;display:block}
.ee-ig__badge{position:absolute;right:8px;bottom:8px;display:grid;place-items:center;width:30px;height:30px;border-radius:999px;background:rgba(255,253,248,.92);color:var(--rosa-700)}
@media (prefers-reduced-motion:reduce){.ee-ig__foto{transition:none}}

/* 5 categorías */

const CLAVE = "ee-pedido-v1";
const IG = "https://www.instagram.com/emilia.estampa/";
const WA = "https://wa.me/56922575539";

function IgIcon({ size = 20 }) {
  return (
    <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
      <rect x="2" y="2" width="20" height="20" rx="5" /><path d="M16 11.37A4 4 0 1 1 12.63 8 4 4 0 0 1 16 11.37z" /><line x1="17.5" y1="6.5" x2="17.51" y2="6.5" />
    </svg>
  );
}

/* Fotos del catálogo que llevan al perfil de Instagram */
function InstagramSeccion() {
  const d = window.EE_CATALOGO;
  const fotos = d.productos.filter(p => p.foto).slice(0, 6);
  return (
    <section className="ee-sec ee-sec--soft ee-band--rosa ee-ig" aria-label="Instagram">
      <div className="ee-ig__head">
        <span className="ee-overline">Síguenos en Instagram</span>
        <a className="ee-ig__user" href={IG} target="_blank" rel="noopener">@emilia.estampa</a>
        <p>Pedidos recién terminados, ideas para regalar y novedades del taller. Síguenos y escríbenos cuando quieras.</p>
      </div>
      {fotos.length > 0 && (
        <div className="ee-ig__grid">
          {fotos.map(p => (
            <a key={p.id} className="ee-ig__foto" href={IG} target="_blank" rel="noopener" aria-label={p.nombre + " en el Instagram de Emilia Estampa"}>
              <img src={p.foto} alt="" loading="lazy" />
              <span className="ee-ig__badge"><IgIcon size={15} /></span>
            </a>
          ))}
        </div>
      )}
      <div className="ee-row">
        <Button as="a" href={IG} target="_blank" rel="noopener">Seguir en Instagram</Button>
        <Button variant="secondary" as="a" href={WA} target="_blank" rel="noopener" icon="message-circle">Escríbenos por WhatsApp</Button>
      </div>
    </section>
  );
}

React.useEffect(() => { registrar("visita"); }, []);
React.useEffect(() => {
  const q = new URLSearchParams(window.location.search);
  const p = q.get("producto") && d.productos.find(x => x.id === q.get("producto"));
  const c = q.get("cat"), v = { "catalogo": "Catálogo", "como-pedir": "Cómo pedir", "faq": "Preguntas frecuentes" }[q.get("ir")];
  if (p) verProducto(p);
  else if (c && d.categorias.some(x => x.id === c)) irCategoria(c);
  else if (v) window.setTimeout(() => ir(v), 300);
}, []);
